import type { ReactNode } from "react";
import { Wave, type WaveState } from "@/components/panel/wave";
import type { Scene } from "@/lib/panel-focus";

const SCENES: Scene[] = ["aube", "matin", "dore", "nuit"];

// The painted gate above Bali (generated by Nathan, public/panel/*.jpg), hung at the top of the panel like a picture
// on the wall. The four times of day are stacked and cross-fade; the picture gets shorter when there is more to read.
export function Painting({ scene, compact, wave, mic }: { scene: Scene; compact: boolean; wave: WaveState; mic?: ReactNode }) {
  return (
    <div className="np-frame" data-compact={compact}>
      <div className="np-picture" aria-hidden>
        {SCENES.map((name) => (
          <div key={name} className="np-scene" data-on={name === scene} style={{ backgroundImage: `url(/panel/${name}.jpg)` }} />
        ))}
        <Wave state={wave} />
      </div>
      {mic ? <div className="np-mic-slot">{mic}</div> : null}
    </div>
  );
}
